	secret, _ := createAPIKey(t, server, cookie, csrf, name, scopes...)
	return secret
}

func createAPIKey(
	t *testing.T,
	server *Server,
	cookie *http.Cookie,
	csrf string,
	name string,
	scopes ...string,
